#include <iostream>
#include <string>
#include <vector>

int main()
{
    int cap{};
    int m{};
    std::cin >> cap >> m;

    std::vector<int> buf(static_cast<std::size_t>(cap), 0);
    std::size_t count{ 0 };

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        std::cin >> cmd;

        if (cmd == "push")
        {
            int x{};
            std::cin >> x;
            // full? otherwise store at buf[count] and ++count
        }
        else if (cmd == "pop")
        {
            // empty? otherwise --count and report buf[count]
        }
        else if (cmd == "top")
        {
            // empty? otherwise report buf[count - 1]
        }
        else if (cmd == "size")
        {
            std::cout << "size " << count << "\n";
        }
    }

    return 0;
}

