import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    cap = int(data[pos]); pos += 1
    m = int(data[pos]); pos += 1

    buf = [0] * cap      # allocate once; do not append
    count = 0

    for _ in range(m):
        cmd = data[pos]; pos += 1
        if cmd == "push":
            x = int(data[pos]); pos += 1
            # full? otherwise buf[count] = x; count += 1
        elif cmd == "pop":
            pass
        elif cmd == "top":
            pass
        elif cmd == "size":
            print("size %d" % count)

main()
